<style>
@page{size:A4 portrait;margin:12mm 10mm}
body{margin:0;color:#000;font-family:DejaVu Sans,Arial,sans-serif;font-size:8.5pt;line-height:1.15}
.sheet{page-break-before:always}.sheet:first-child{page-break-before:auto}
h1{margin:0;font-size:11pt;text-decoration:underline;line-height:1.3}
.report-heading{text-align:center;margin-bottom:4mm}.report-heading p{margin:0;font-size:9pt;font-style:italic;font-weight:bold;color:#555}
table{width:100%;border-collapse:collapse;table-layout:fixed}td,th{vertical-align:top;overflow-wrap:break-word}
.identity{margin-bottom:4mm}.identity td{padding:1pt 0}.identity td:first-child{width:36%}.identity .colon{width:3%}
h2{margin:0 0 2pt;font-size:9pt}em{font-style:italic}
.grades th,.grades td{border:.6pt solid #000;padding:2.5pt 4pt}.grades th{vertical-align:middle;text-align:center}.grades .number{width:6%}.grades .aspect{width:27%}.grades .rating{width:10%}.center{text-align:center;vertical-align:middle!important}
thead{display:table-header-group}tr{page-break-inside:avoid}.item-note{margin-top:3pt;font-size:8pt}
.comments{margin-top:-.6pt;border:.6pt solid #000}.comments h3{font-size:8.5pt;margin:0;padding:4pt;border-bottom:.6pt solid #000}.comments-content{padding:4pt;min-height:18mm}.prose{white-space:pre-wrap}.focus{margin-top:5pt;white-space:pre-wrap}
.signature-section{page-break-inside:avoid}.report-date{margin:3pt 0 0 8%;font-size:9pt}.signatures td{width:50%;text-align:center;vertical-align:bottom}.sign-space{height:15mm}.signature-name{text-decoration:underline}.signature-line{display:inline-block;width:48mm;border-bottom:.6pt solid #000}.acknowledged{text-align:center;margin:3mm 0 0}
</style>
